    StringBuilder sb = new StringBuilder();
    StringBuilder escaped = new StringBuilder("\\'");

    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < str.length()) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case 't':
                        sb.append("\t");
                        i++;
                        break;
                    case 'n':
                        sb.append("\n");
                        i++;
                        break;
                    case 'b':
                        sb.append("\b");
                        i++;
                        break;
                    case 'r':
                        sb.append("\r");
                        i++;
                        break;
                    case 'f':
                        sb.append("\f");
                        i++;
                        break;
                    case '\\':
                        sb.append("\\\\");
                        i++;
                        break;
                    default:
                        // if not handled, just append back the double backslash
                        escaped.append(nextChar);
                        break;
                }
            } else {
                // if the next character does not exist (as is common with some poor JSON/json.NET describers)
                // then just append the double backslash
                escaped.append(nextChar);
            }
        } else {
            if (escaped.length() > 0) {
                sb.append(escaped);
                escaped = new StringBuilder("\\'");
            }
            sb.append(c);
        }
    }

    // handle the last escapement remaining
    if (escaped.length() > 0) {
        sb.append(escaped);
    }

    return sb.toString();
}

